  FT["PH-H7299"] = {"id":"PH-H7299","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8831_2000.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Quezon市","en":"An Act Establishing a National High School in Barangay Panitian, Municipality of Quezon, Province of Palawan, to Be Known as the Quezon-Panitian National High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Panitian, Municipality of Quezon, Province of Palawan, to Be Known as the Quezon-Panitian National High School, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Barangay Panitian, Thị trấn Quezon, Tỉnh Palawan được biết đến với tên gọi Trường trung học phổ thông quốc gia Quezon-Panitian","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในบารังไกย์ Panitian, เทศบาล Quezon, จังหวัด Palawan ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ Quezon-Panitian","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Barangay Panitian, Kotamadya Quezon, Provinsi Palawan dikenal sebagai Sekolah Menengah Atas Nasional Quezon-Panitian","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Barangay Panitian, Perbandaran Quezon, Wilayah Palawan dikenali sebagai Sekolah Menengah Kebangsaan Quezon-Panitian"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8831","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8831_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7299-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There is hereby established a national high school in Barangay Panitian, Municipality of Quezon, Province of Palawan, to be known as the Quezon-Panitian National High School."}},{"id":"PH-H7299-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue the necessary rules, circulars and regulations to implement this Act."}},{"id":"PH-H7299-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7299-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, August 22, 2000."}}],"pack":"ph-p104"};
