  FT["PH-H7332"] = {"id":"PH-H7332","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8864_2000.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Loboc市","en":"An Act Establishing a National High School in Barangay Camayaan, Municipality of Loboc, Province of Bohol, to Be Known as Camayaan National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Camayaan, Municipality of Loboc, Province of Bohol, to Be Known as Camayaan National High School and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Barangay Camayaan, Thị trấn Loboc, Tỉnh Bohol được biết đến với tên gọi Trường trung học phổ thông quốc gia Camayaan","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในบารังไกย์ Camayaan, เทศบาล Loboc, จังหวัด Bohol ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ Camayaan","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Barangay Camayaan, Kotamadya Loboc, Provinsi Bohol dikenal sebagai Sekolah Menengah Atas Nasional Camayaan","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Barangay Camayaan, Perbandaran Loboc, Wilayah Bohol dikenali sebagai Sekolah Menengah Kebangsaan Camayaan"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8864","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8864_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7332-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established under the direct supervision of the Department of Education, Culture and Sports, a national high school in Barangay Camayaan, Municipality of Loboc, Province of Bohol to be known as Camayaan National High School."}},{"id":"PH-H7332-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H7332-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7332-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p104"};
  FT["PH-H7333"] = {"id":"PH-H7333","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8865_2000.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Bilar市","en":"An Act Converting the Bilar High School, Municipality of Bilar, Province of Bohol Into a National High School to Be Known as the Bilar National High School, Appropriating Funds Therefor and for Other Purposes","orig":"An Act Converting the Bilar High School, Municipality of Bilar, Province of Bohol Into a National High School to Be Known as the Bilar National High School, Appropriating Funds Therefor and for Other Purposes","vi":"Đạo luật chuyển đổi Bilar High School, Municipality of Bilar, Province of Bohol thành Bilar National High School","th":"พระราชบัญญัติเปลี่ยนสถานะ Bilar High School, Municipality of Bilar, Province of Bohol เป็น Bilar National High School","id":"Undang-Undang mengubah Bilar High School, Municipality of Bilar, Province of Bohol menjadi Bilar National High School","ms":"Akta menukar Bilar High School, Municipality of Bilar, Province of Bohol kepada Bilar National High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8865","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8865_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7333-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Bilar High School of the Municipality of Bilar, Province of Bohol is hereby converted into a national high school to be known as the Bilar National High School under the direct supervision of the Department of Education, Culture and Sports."}},{"id":"PH-H7333-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H7333-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7333-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p104"};
  FT["PH-H7334"] = {"id":"PH-H7334","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8866_2000.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Kabugao市","en":"An Act Establishing a National High School At Madatag, Municipality of Kabugao, Province of Apayao to Be Known as Mayor Bartolome Serut National Agricultural and Trade High School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School At Madatag, Municipality of Kabugao, Province of Apayao to Be Known as Mayor Bartolome Serut National Agricultural and Trade High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["trade","education","environment"],"docNumber":"Republic Act No. 8866","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8866_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7334-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a national high school at Madatag, Municipality of Kabugao, Province of Apayao to be known as Mayor Bartolome Serut National Agricultural and Trade High School."}},{"id":"PH-H7334-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The school shall offer secondary education proper as well as other vocational courses to carry out its objectives as may be authorized by the Secretary of the Department of Education, Culture and Sports (DECS) and in coordination with the Technical Education and Skills Development Authority (TESDA) and other appropriate offices and agencies."}},{"id":"PH-H7334-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Education, Culture and Sports shall issue rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H7334-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7334-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p104"};
  FT["PH-H7335"] = {"id":"PH-H7335","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8867_2000.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将卡林加省Pinukpuk市镇的Ammacian中学（即Pinukpuk职业中学附属校）分离为独立的Cal-Owan农业职业国立中学，并拨款","en":"An Act Separating the Ammacian Barangay High School, Also Known as Pinukpuk Vocational School-Ammacian Annex in the Municipality of Pinukpuk, Province of Kalinga, From the Pinukpuk Vocational School in the Municipality of Pinukpuk, and Converting It Into a National Agricultural and Vocational High School to Be Known as the Cal-Owan Agricultural and Vocational National High School, and Appropriating Funds Therefor","orig":"An Act Separating the Ammacian Barangay High School, Also Known as Pinukpuk Vocational School-Ammacian Annex in the Municipality of Pinukpuk, Province of Kalinga, From the Pinukpuk Vocational School in the Municipality of Pinukpuk, and Converting It Into a National Agricultural and Vocational High School to Be Known as the Cal-Owan Agricultural and Vocational National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education","environment"],"docNumber":"Republic Act No. 8867","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8867_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 6 条，缺 3）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7335-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Ammacian Barangay High School, also known as Pinukpuk Vocational School - Ammacian Annex in the Municipality of Pinukpuk, Province of Kalinga, is hereby separated from the Pinukpuk Vocational School in the Municipality of Pinukpuk and converted into a national agricultural and vocational high school to be known as the Cal-Owan Agricultural and Vocational National High School."}},{"id":"PH-H7335-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The school shall, in addition to its present secondary curriculum, offer technical and other vocational subjects.\nSec. 3. The Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H7335-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"All personnel, records, assets and liabilities of the Ammacian Barangay High School are hereby transferred to and absorbed by the Cal-Owan Agricultural and Vocational National High School."}},{"id":"PH-H7335-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Pinukpuk Vocational School - Ammacian Annex. Thereafter, such sums as may be necessary for the operation and maintenance of the Cal-Owan Agricultural and Vocational National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H7335-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval.\nApproved, August 22, 2000."}}],"pack":"ph-p104","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Ammacian Barangay High School, Also Known as Pinukpuk Vocational School-Ammacian Annex in the Municipality of Pinukpuk, Province of Kalinga, From the Pinukpuk Vocational School in the Municipality of Pinukpuk, and Converting It Into a National Agricultural and Vocational High School to Be Known as the Cal-Owan Agricultural and Vocational National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H7336"] = {"id":"PH-H7336","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8868_2000.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Sagada市","en":"An Act Establishing a National High School in the Municipality of Sagada, Mountain Province to Be Known as the Sagada National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in the Municipality of Sagada, Mountain Province to Be Known as the Sagada National High School and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Thị trấn Sagada, Tỉnh Mountain được biết đến với tên gọi Trường trung học phổ thông quốc gia Sagada","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในเทศบาล Sagada, จังหวัด Mountain ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ Sagada","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Kotamadya Sagada, Provinsi Mountain dikenal sebagai Sekolah Menengah Atas Nasional Sagada","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Perbandaran Sagada, Wilayah Mountain dikenali sebagai Sekolah Menengah Kebangsaan Sagada"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8868","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8868_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7336-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, Culture and Sports, a national high school in the Municipality of Sagada, Mountain Province to be known as the Sagada National High School."}},{"id":"PH-H7336-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H7336-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7336-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p104"};
  FT["PH-H7337"] = {"id":"PH-H7337","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8869_2000.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Besao市","en":"An Act Establishing a National High School in the Municipality of Besao, Mountain Province to Be Known as the Besao National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in the Municipality of Besao, Mountain Province to Be Known as the Besao National High School and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Thị trấn Besao, Tỉnh Mountain được biết đến với tên gọi Trường trung học phổ thông quốc gia Besao","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในเทศบาล Besao, จังหวัด Mountain ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ Besao","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Kotamadya Besao, Provinsi Mountain dikenal sebagai Sekolah Menengah Atas Nasional Besao","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Perbandaran Besao, Wilayah Mountain dikenali sebagai Sekolah Menengah Kebangsaan Besao"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8869","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8869_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7337-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Education, Culture and Sports, a national high school in the Municipality of Besao, Mountain Province to be known as the Besao National High School."}},{"id":"PH-H7337-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H7337-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7337-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p104"};
  FT["PH-H7338"] = {"id":"PH-H7338","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8870_2000.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将高山省 Sadanga 市镇 Betwagan 描笼涯的 Sadanga 国立中学的 Betwagan 附属校分离，改设为独立的同名国立中学，并为此拨款","en":"An Act Separating the Sadanga National High School-Betwagan Annex in Barangay Betwagan, Municipality of Sadanga, Mountain Province From the Sadanga National High School in the Municipality of Sadanga, Mountain Province and Converting the Same Into An Independent National High School to Be Known as the Betwagan National High School, and Appropriating Funds Therefor","orig":"An Act Separating the Sadanga National High School-Betwagan Annex in Barangay Betwagan, Municipality of Sadanga, Mountain Province From the Sadanga National High School in the Municipality of Sadanga, Mountain Province and Converting the Same Into An Independent National High School to Be Known as the Betwagan National High School, and Appropriating Funds Therefor","vi":"Đạo luật tách Phân hiệu Betwagan của Trường Trung học Sadanga Quốc gia tại Barangay Betwagan, Đô thị Sadanga, Tỉnh Mountain Province khỏi Trường Trung học Sadanga Quốc gia và chuyển thành Trường Trung học Độc lập Quốc gia với tên gọi Trường Trung học Betwagan Quốc gia, và bố trí kinh phí","th":"พระราชบัญญัติแยกวิทยาเขต Betwagan ของโรงเรียนมัธยมศึกษา Sadanga แห่งชาติในบารังไกย์ Betwagan เทศบาล Sadanga จังหวัด Mountain Province ออกจากโรงเรียนมัธยมศึกษา Sadanga แห่งชาติและยกฐานะเป็นโรงเรียนมัธยมศึกษาเอกเทศแห่งชาติชื่อโรงเรียนมัธยมศึกษา Betwagan แห่งชาติ และจัดสรรงบประมาณ","id":"Undang-Undang Memisahkan Kampus Betwagan, Sekolah Menengah Sadanga Nasional di Barangay Betwagan, Kotamadya Sadanga, Provinsi Mountain Province dari Sekolah Menengah Sadanga Nasional dan menjadi Sekolah Menengah Mandiri Nasional dengan nama Sekolah Menengah Betwagan Nasional, dan mengalokasikan dana","ms":"Akta Memisahkan Kampus Betwagan, Sekolah Menengah Sadanga Kebangsaan di Barangay Betwagan, Perbandaran Sadanga, Wilayah Mountain Province daripada Sekolah Menengah Sadanga Kebangsaan dan menjadi Sekolah Menengah Bebas Kebangsaan dengan nama Sekolah Menengah Betwagan Kebangsaan, dan memperuntukkan dana"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8870","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8870_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7338-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Sadanga National High School - Betwagan Annex in Barangay Betwagan, Municipality of Sadanga, Mountain Province is hereby separated from the Sadanga National High School in the Municipality of Sadanga, Mountain Province and converted into an independent national high school to be known as the Betwagan National High School."}},{"id":"PH-H7338-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such orders, rules and circulars as may be necessary for the implementation of this Act."}},{"id":"PH-H7338-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, records, assets and liabilities of the Sadanga National High School - Betwagan Annex are hereby transferred to and absorbed by the Betwagan National High School."}},{"id":"PH-H7338-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary for the implementation of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7338-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p104","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Sadanga National High School-Betwagan Annex in Barangay Betwagan, Municipality of Sadanga, Mountain Province From the Sadanga National High School in the Municipality of Sadanga, Mountain Province and Converting the Same Into An Independent National High School to Be Known as the Betwagan National High School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H7339"] = {"id":"PH-H7339","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8871_2000.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将高山省 Bontoc 市镇 Guinaang 描笼涯的 Mountain Province General 综合中学附属校分离，改设为独立的同名国立中学，并为此拨付所需经费","en":"An Act Separating the Mountain Province General Comprehensive High School -Guinaang Annex Located in Barangay Guinaang, Municipality of Bontoc, Mountain Province From the Mountain Province General Comprehensive High School Located in the Municipality of Bontoc, Mountain Province and the Same Is Converted Into An Independent National High School to Be Known as the Guinaang National High School and Appropriating Funds Therefor","orig":"An Act Separating the Mountain Province General Comprehensive High School -Guinaang Annex Located in Barangay Guinaang, Municipality of Bontoc, Mountain Province From the Mountain Province General Comprehensive High School Located in the Municipality of Bontoc, Mountain Province and the Same Is Converted Into An Independent National High School to Be Known as the Guinaang National High School and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8871","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8871_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7339-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Mountain Province Comprehensive High School - Guinaang Annex located in Barangay Guinaang, Municipality of Bontoc, Mountain Province is hereby separated from the Mountain Province General Comprehensive High School located in the Municipality of Bontoc, Mountain Province and the same is converted into an independent national high school to be known as the Guinaang National High School."}},{"id":"PH-H7339-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports (DECS) shall issue such rules and regulations as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H7339-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, records, assets and liabilities of the Mountain Province General Comprehensive High School -Guinaang Annex are hereby transferred to and absorbed by the Guinaang National High School."}},{"id":"PH-H7339-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary for the initial implementation of this Act shall be charged against the current year's appropriations of the Mountain Province General Comprehensive High School - Guinaang Annex. Thereafter, such sums as may be necessary for the continuous operation and maintenance of the Guinaang National High School shall be included in the annual General Appropriations Act."}},{"id":"PH-H7339-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p104","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Separating the Mountain Province General Comprehensive High School -Guinaang Annex Located in Barangay Guinaang, Municipality of Bontoc, Mountain Province From the Mountain Province General Comprehensive High School Located in the Municipality of Bontoc, Mountain Province and the Same Is Converted Into An Independent National High School to Be Known as the Guinaang National High School and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
