  FT["PH-H7344"] = {"id":"PH-H7344","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra2000/ra_8876_2000.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Pototan市","en":"An Act Establishing a National High School in Barangay Iwa Macatol, Municipality of Pototan, Province of Iloilo to Be Known as Alberto Sorongon Sr. Memorial National High School and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in Barangay Iwa Macatol, Municipality of Pototan, Province of Iloilo to Be Known as Alberto Sorongon Sr. Memorial National High School and Appropriating Funds Therefor","vi":"Đạo luật thành lập Trường trung học phổ thông quốc gia tại Barangay Iwa Macatol, Thị trấn Pototan, Tỉnh Iloilo được biết đến với tên gọi Trường trung học phổ thông quốc gia Alberto Sorongon Sr. Memorial","th":"พระราชบัญญัติจัดตั้งโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติในบารังไกย์ Iwa Macatol, เทศบาล Pototan, จังหวัด Iloilo ให้เป็นที่รู้จักในชื่อโรงเรียนมัธยมศึกษาตอนปลายแห่งชาติ Alberto Sorongon Sr. Memorial","id":"Undang-Undang mendirikan Sekolah Menengah Atas Nasional di Barangay Iwa Macatol, Kotamadya Pototan, Provinsi Iloilo dikenal sebagai Sekolah Menengah Atas Nasional Alberto Sorongon Sr. Memorial","ms":"Akta menubuhkan Sekolah Menengah Kebangsaan di Barangay Iwa Macatol, Perbandaran Pototan, Wilayah Iloilo dikenali sebagai Sekolah Menengah Kebangsaan Alberto Sorongon Sr. Memorial"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8876","issuingBody":"Congress of the Philippines","promulgatedDate":"2000-08-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra2000/ra_8876_2000.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H7344-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a national high school in Barangay Iwa Macatol, Municipality of Pototan, Province of Iloilo to be known as Alberto Sorongon Sr. Memorial National High School."}},{"id":"PH-H7344-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports is hereby authorized to issue such rules and regulations as may be necessary to carry out the purpose of this Act."}},{"id":"PH-H7344-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H7344-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p104"};
